#include <cstdio>
#include <iostream>
using namespace std;

long long int powers_of_ten[18];
int answer=0;

void search(int current_sum, long long int remaining, int position)
{
    if(current_sum > answer)
        return;
    if(remaining == 0)
    {
        answer = min(answer, current_sum);
        return;
    }
    int count = remaining / powers_of_ten[position];
    search(current_sum + position * count++, remaining - count * powers_of_ten[position], position - 1);
    search(current_sum + count * position, count * powers_of_ten[position] - remaining, position - 1);
}

int main()
{
    long long int num;
    cin >> num;
    powers_of_ten[1] = 1;
    for(int i=2; i<18; i++)
        powers_of_ten[i] = (10 * powers_of_ten[i-1]) + 1;
    long long int temp_num = num;
    answer = 0;
    while(temp_num > 0)
    {
        for(int i=1; i<18; i++)
        {
            if(powers_of_ten[i] > temp_num)
            {
                answer += (i - 1);
                temp_num -= powers_of_ten[i - 1];
                break;
            }
        }
    }
    search(0, num, 16);
    cout << answer << endl;
}
